var e=document.querySelector(`[data-seller-daily-chart]`);if(e&&window.ApexCharts){let t=document.getElementById(`dailyChart`);try{let n=JSON.parse(e.dataset.sales||`[]`),r=JSON.parse(e.dataset.days||`[]`);new ApexCharts(t,{chart:{type:`bar`,height:220,toolbar:{show:!1}},series:[{name:`Sales (PHP)`,data:n}],xaxis:{categories:r,labels:{rotate:-45,style:{fontSize:`10px`}}},colors:[`#E8472A`],dataLabels:{enabled:!1},yaxis:{labels:{formatter:e=>`PHP `+e.toLocaleString()}},tooltip:{y:{formatter:e=>`PHP `+e.toLocaleString()}},grid:{borderColor:`#e7e1d8`}}).render()}catch(e){console.error(`Unable to render seller daily chart.`,e)}}